-- ============================================================================
-- EC11: Reserves & Resources under SPE-PRMS 2018 joins the catalogue in the
-- Economics & Commercial module. AN ENGINE COURSE: there is no Suite app; the
-- practicals run in the course's own calculator panels.
--
-- Catalogue row (module 'economics'; path_order 76; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/prms/gen_course.py
-- from the ENGINE'S OWN RUN (prms_capstone.mjs through the vendored
-- engines/economics/prms.js, petrolord-engines bb8ef5f), which it refuses to
-- write unless fields.json carries exactly that run's values and the tolerance
-- gradedTolerance.js derives. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries the
-- route /dashboard/apps/prms.
--
-- WHAT IS GRADED. ABAGANA (Associate) grades the chance of commerciality of a
-- prospect and of a lead, the Probable and Possible increments of a Reserves
-- set and the 2C and 3C of a Contingent Resources set; AWKUZU (Professional)
-- grades the best case's undiscounted net cash flow and NPV at the working
-- interest, the 2P net entitlement oil, the P2 and P3 increments in BOE with
-- the low case failing, and the high case's oil beyond the licence; ISUOFIA
-- (Expert) grades the arithmetic 1P and 3P of three Reserves projects, the
-- risked mean of three Contingent Resources projects and a reconciliation's
-- computed closing 1P and 3P and 2P difference. Every value is a return value
-- of the engine, identical under every reading the engine states and never a
-- Monte Carlo draw, and the data it was run on is in the case file the prompt
-- names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('prms', 'Reserves & Resources under SPE-PRMS 2018', 'economics', 76, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'prms', 'beginner', 'associate',
  'ABAGANA, the resources of the Abagana licence (synthetic)',
  'Classes, categories and the low estimate',
  'ABAGANA, the resources of the Abagana licence (synthetic). One case file comes with this capstone: abagana_case.json carries four calls under the keys classify:prospect, classify:lead, categorize:reserves and categorize:contingent; paste it into the classification calculator and choose the block each value needs. The Abagana Deep prospect is undiscovered, with a project of established technology, sub-class prospect, and a chance of geologic discovery of 23.5 percent and a chance of development of 61.3 percent. The Abagana Shallow lead is undiscovered, with a project of established technology, sub-class lead, and a chance of geologic discovery of 12.25 percent and a chance of development of 47.5 percent. The Abagana Reserves are stated cumulatively in MMbbl: low 11.35, best 18.62, high 27.415. The Abagana Contingent Resources are stated incrementally in MMboe: first 4.215, second 3.37, third 5.605. No value depends on any of the readings the engine states (the five-year benchmark, the economic test at exactly 0 and with abandonment, the economic-limit rule, the replacement ratio, the life index, the tolerance at its boundary, the Monte Carlo low) or on a Monte Carlo draw, and every input a value needs is stated in the case file: the engine holds no default for any of them. Report six values: the chance of commerciality of the Abagana Deep prospect, in percent; the chance of commerciality of the Abagana Shallow lead, in percent; the Probable (P2) increment of the Reserves; the Possible (P3) increment of the Reserves; the 2C of the Contingent Resources; and the 3C of the Contingent Resources. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','abagana_prospect_pc_pct', 'label','The chance of commerciality of the Abagana Deep prospect', 'unit','percent', 'expected',14.4055, 'tol',5e-07),
    jsonb_build_object('key','abagana_lead_pc_pct', 'label','The chance of commerciality of the Abagana Shallow lead', 'unit','percent', 'expected',5.81875, 'tol',5e-07),
    jsonb_build_object('key','abagana_reserves_p2', 'label','The Probable (P2) increment of the Abagana Reserves', 'unit','MMbbl', 'expected',7.270000000000001, 'tol',5e-07),
    jsonb_build_object('key','abagana_reserves_p3', 'label','The Possible (P3) increment of the Abagana Reserves', 'unit','MMbbl', 'expected',8.794999999999998, 'tol',5e-07),
    jsonb_build_object('key','abagana_contingent_2c', 'label','The 2C of the Abagana Contingent Resources', 'unit','MMboe', 'expected',7.585, 'tol',5e-07),
    jsonb_build_object('key','abagana_contingent_3c', 'label','The 3C of the Abagana Contingent Resources', 'unit','MMboe', 'expected',13.190000000000001, 'tol',5e-07)
  )
),
(
  'prms', 'intermediate', 'professional',
  'AWKUZU, the economic limit of the Awkuzu field (synthetic)',
  'Maturity, commerciality and the economic limit',
  'AWKUZU, the economic limit of the Awkuzu field (synthetic). One case file comes with this capstone: awkuzu_case.json carries one call under the key economicLimit; paste it into the reserves calculator''s economic limit view. The three technical forecasts (oil in barrels and gas in Mscf, one row a year from 2029 to 2044), the prices and the opex and capex rows are in the case file. Effective year 2029; a royalty of 12.5 percent as a royalty-interest; tax at 32.5 percent with 5-year straight-line allowances and lossCarryforward true; a working interest of 57.5 percent; a licence expiring in 2041 with renewalExpected false; the net-entitlement basis; a discount rate of 10 percent; 6 Mscf per BOE; an abandonment cost of 27500000. The undiscounted net cash flow is after tax and abandonment. No value depends on any of the readings the engine states (the five-year benchmark, the economic test at exactly 0 and with abandonment, the economic-limit rule, the replacement ratio, the life index, the tolerance at its boundary, the Monte Carlo low) or on a Monte Carlo draw, and every input a value needs is stated in the case file: the engine holds no default for any of them. Report six values: the best case''s undiscounted net cash flow at the working interest; the best case''s NPV at the working interest; the 2P oil on the net-entitlement basis; the Probable (P2) increment in BOE; the Possible (P3) increment in BOE; and the high case''s oil beyond the licence, gross. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','awkuzu_best_ncf_share', 'label','The best case''s undiscounted net cash flow at the working interest', 'unit','USD', 'expected',58168493.64463964, 'tol',5e-07),
    jsonb_build_object('key','awkuzu_best_npv_share', 'label','The best case''s NPV at the working interest', 'unit','USD', 'expected',39957040.64785222, 'tol',5e-07),
    jsonb_build_object('key','awkuzu_2p_net_oil', 'label','The 2P oil on the net-entitlement basis', 'unit','bbl', 'expected',4827321.739843749, 'tol',5e-07),
    jsonb_build_object('key','awkuzu_p2_boe', 'label','The Probable (P2) increment in BOE', 'unit','BOE', 'expected',5350281.583463541, 'tol',5e-07),
    jsonb_build_object('key','awkuzu_p3_boe', 'label','The Possible (P3) increment in BOE', 'unit','BOE', 'expected',3549723.34609375, 'tol',5e-07),
    jsonb_build_object('key','awkuzu_high_beyond_licence_oil', 'label','The high case''s oil beyond the licence, gross', 'unit','bbl', 'expected',1474129.5, 'tol',5e-07)
  )
),
(
  'prms', 'advanced', 'expert',
  'ISUOFIA, the aggregation and reconciliation of the Isuofia field (synthetic)',
  'Aggregation, reconciliation and the limits',
  'ISUOFIA, the aggregation and reconciliation of the Isuofia field (synthetic). One case file comes with this capstone: isuofia_case.json carries three calls under the keys aggregate:reserves, aggregate:contingent and reconcile; paste it into the aggregation calculator and choose the block each value needs. The Reserves projects, aggregated at the field level in MMbbl: ISF-1: a lognormal with mean 7.35 and standard deviation 2.15; ISF-2: a normal with mean 5.42 and standard deviation 0.87; ISF-3: a triangular with min 2.1, mode 3.65 and max 6.4; a uniform correlation of 0.35, seed 20291204, 5000 draws. The Contingent Resources projects in MMboe: ISF-4: a triangular with min 1.8, mode 3.2 and max 7.9, chance of commerciality 55.5 percent; ISF-5: a lognormal with mean 4.65 and standard deviation 1.9, chance of commerciality 38.25 percent; ISF-6: a normal with mean 2.95 and standard deviation 0.6, chance of commerciality 71.4 percent; a uniform correlation of 0.2, seed 20291205, 5000 draws. The reconciliation of the Reserves in MMbbl over 1 year: opening low 24.6, best 33.85, high 45.2; movements production of 2.35; revisions of 0.42, -0.31 and -1.05; extensions-and-discoveries of 1.15, 2.4 and 3.95; divestments of 0.8, 1.1 and 1.45; transfers of 2.2, 3.35 and 4.6; stated closing low 25.3, best 36.137, high 49.35; tolerance 0.001. No value depends on any of the readings the engine states (the five-year benchmark, the economic test at exactly 0 and with abandonment, the economic-limit rule, the replacement ratio, the life index, the tolerance at its boundary, the Monte Carlo low) or on a Monte Carlo draw, and every input a value needs is stated in the case file: the engine holds no default for any of them. Report six values: the arithmetic 1P of the Reserves projects; the arithmetic 3P of the Reserves projects; the risked mean of the Contingent Resources; the computed closing 1P of the reconciliation; the computed closing 3P; and the 2P difference, the stated closing less the computed. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','isuofia_reserves_arith_1p', 'label','The arithmetic 1P of the Isuofia Reserves projects', 'unit','MMbbl', 'expected',12.107774398049704, 'tol',5e-07),
    jsonb_build_object('key','isuofia_reserves_arith_3p', 'label','The arithmetic 3P of the Isuofia Reserves projects', 'unit','MMbbl', 'expected',22.031925128837223, 'tol',5e-07),
    jsonb_build_object('key','isuofia_contingent_risked_mean', 'label','The risked mean of the Isuofia Contingent Resources', 'unit','MMboe', 'expected',6.271425, 'tol',5e-07),
    jsonb_build_object('key','isuofia_closing_1p', 'label','The computed closing 1P of the Isuofia reconciliation', 'unit','MMbbl', 'expected',25.22, 'tol',5e-07),
    jsonb_build_object('key','isuofia_closing_3p', 'label','The computed closing 3P of the Isuofia reconciliation', 'unit','MMbbl', 'expected',48.900000000000006, 'tol',5e-07),
    jsonb_build_object('key','isuofia_difference_2p', 'label','The 2P difference, the stated closing less the computed', 'unit','MMbbl', 'expected',0.29699999999999704, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
